　ルート1｜壁量・柱量の簡易チェック｜小規模な建物
　ルート2｜剛性率・偏心率の確認｜ルート1よりやや規模が大きい建物★
　ルート3｜保有水平耐力計算（Ds使用）｜高さ・規模が大きく複雑な建物★

