・あばら筋（スターラップ）は梁の主筋を囲むように配置される横方向の鉄筋で、柱の帯筋と同じ役割を果たす★
・梁端部は地震時の曲げモーメントが最大になる位置であり、あばら筋を密に配置する
・あばら筋の間隔が広すぎると、斜めひび割れを抑えきれずせん断破壊に至りやすい

