　破壊形式｜変形能力｜設計上の扱い
　曲げ破壊｜大きい（粘り強い）｜先に生じることを許容し、エネルギー吸収に利用★
　せん断破壊｜小さい（急激）｜曲げ耐力より大きい耐力を確保し、発生自体を防ぐ★

