━━━━━━━━━━━━━━━━━━━━━━
・完全溶込み溶接：母材の全断面を溶接金属で一体化する方法。母材と同等の強度を期待できる★
・隅肉溶接：部材の隅角部に三角形状の溶接を施す方法。施工は容易だが耐力は完全溶込みより劣る
