・梁端部のフランジは完全溶込み溶接、ウェブは高力ボルト接合とする組合せが広く使われる★
・この組合せは、曲げを負担するフランジに信頼性の高い溶接を、せん断を負担するウェブに施工性の良いボルトを使う合理的な設計
