━━━━━━━━━━━━━━━━━━━━━━
・耐震構造：建物の強度・靭性で地震力に抵抗する。コストは比較的抑えやすいが建物内部の揺れは大きい
・制震構造：ダンパーで揺れを吸収し、建物の損傷や居住者の不快感を軽減する★
・免震構造：地震力そのものを建物に伝えにくくし、3つの中で建物内部の揺れを最も小さくできる★

