・開口の角（コーナー部）は特に応力が集中しやすく、ひび割れの起点になりやすい
・開口の大きさ・位置によっては補強筋や補強プレートを追加し、応力集中を緩和する設計が必要
・梁せいに対して開口が大きすぎたり、せん断力が大きい位置（梁端部付近）に開口を設けたりするのは避けるのが原則★

━━━━━━━━━━━━━━━━━━━━━━
