        body: `▼ゼロから：基礎の種類が違うと「沈み方」も変わる
・直接基礎と杭基礎のように、支持形式の異なる基礎を同一建物内で併用することを異種基礎の併用という★
・異種基礎は沈下特性（沈下量・沈下速度）が大きく異なるため、原則として併用は避けるべきとされる★
・やむを得ず併用する場合は、エキスパンションジョイントで構造的に縁を切る等の対策が取られる
⚠ 「異種基礎は構造計算上問題なければ併用してよい」は誤り。不同沈下リスクから原則避けるべき考え方が基本

━━━━━━━━━━━━━━━━━━━━━━
🔑 不同沈下の原因と対策
━━━━━━━━━━━━━━━━━━━━━━
・不同沈下は、地盤の不均一性、荷重の偏り、基礎形式の違いなどによって生じる★
・対策としては、地盤改良による地盤の均質化、基礎形式の統一、剛性の高い基礎（べた基礎等）の採用がある
・不同沈下が進行すると、建物の傾斜、ひび割れ、建具の不具合など機能的な支障が生じる

★ここだけ暗記
・異種基礎の併用は沈下特性の違いから原則避ける
・不同沈下対策は地盤改良・基礎形式の統一・剛性の高い基礎の採用など`,
