        emoji: '🔺',
        body: `▼ゼロから：切断法は「欲しい部材だけ」を狙い撃ちする
・水平弦材・斜材・垂直材からなる単純なプラットトラス（三角形の繰り返し）を例に、特定の斜材の軸力を切断法で求める手順を確認する★
・節点法と違い、切断面より片側全体をひとまとめにして解くのが切断法の特徴
⚠ 切断する際は、求めたい部材を含め、未知の軸力が3つ以下になるよう切断面を選ぶ★

━━━━━━━━━━━━━━━━━━━━━━
🔑 切断法の手順
━━━━━━━━━━━━━━━━━━━━━━
・①support反力を先に全体のつり合いから求める
・②求めたい部材（斜材D）を含む3部材（上弦材・下弦材・斜材）を貫く断面で切断する★
・③切断した片側（例えば左側）だけを取り出し、残り2部材の軸力が交わる点でΣM＝0を立てると、斜材の軸力だけが求まる
・④ΣY＝0を使えば、上弦材・下弦材を介さず斜材の鉛直成分だけで解けるケースも多い★

━━━━━━━━━━━━━━━━━━━━━━
🔑 モーメントの基準点の選び方
━━━━━━━━━━━━━━━━━━━━━━
・上弦材と下弦材の軸力を消去したいなら、その2つの作用線の交点でΣMをとる★
・上弦材と下弦材が平行（水平）なトラスでは交点が無限遠になるため、代わりにΣY＝0を使って斜材の鉛直成分から直接解く
・この場合、斜材の軸力＝（鉛直成分の力）／sinθ（θは斜材の傾き角）という変換を忘れない★

【図解】節点法と切断法、それぞれの着目点
　解法｜着目する範囲｜向いているケース
　節点法｜1つの節点｜全部材の軸力を順番に求めたいとき
　切断法｜切断面の片側全体｜特定の1〜2部材だけをピンポイントで求めたいとき★

★ここだけ暗記
・切断法は求めたい部材を含め未知数3つ以下になる面で切る
・平行弦トラスでは斜材はΣY＝0→sinθで割って軸力を求める`,
