        emoji: '🏗️',
        body: `▼ゼロから：多層多スパンのラーメンは「略算法」で大づかみに解く
・実務の厳密な解析はコンピュータが行うが、学科試験では各柱がどれだけの水平力を負担するかを大づかみに把握するD値法（層間せん断力分配法）の考え方が問われる★
・各階の地震層せん断力を、その階の柱の剛性（D値）の比に応じて配分する考え方★
⚠ D値法は柱の「剛比」に応じて水平力を配分する近似法であり、厳密解ではない点に注意

━━━━━━━━━━━━━━━━━━━━━━
🔑 D値（水平剛性）の考え方
━━━━━━━━━━━━━━━━━━━━━━
・D値は、柱の上下端の梁の剛比に応じて補正された、柱1本あたりの水平方向の剛性を表す指標★
・柱断面が太く短いほど（剛性が高いほど）D値は大きくなり、負担するせん断力も大きくなる
・同じ階にある柱のD値の合計に対する、各柱のD値の比率で、その階のせん断力を配分する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 D値法でわかること
━━━━━━━━━━━━━━━━━━━━━━
・剛性の大きい（太短い）柱ほど地震時に多くの水平力を負担し、損傷しやすくなる傾向がある★
・同じ階でも端部の柱と中央の柱で負担するせん断力が異なり、設計の際に個別に確認が必要
・柱の反曲点（曲げモーメントがゼロになる高さ位置）の位置も、梁の剛比に応じて変化する

【図解】D値法のイメージ
　要素｜影響すること
　柱の剛性（断面・高さ）｜D値の大きさ、負担するせん断力の大小★
　上下の梁の剛比｜柱の反曲点位置の補正
　⇒ 剛性の大きい柱に地震力が集中しやすいことを理解しておく

★ここだけ暗記
・D値法は柱の剛性比に応じて層せん断力を配分する略算法
・剛性の大きい柱ほど多くの地震力を負担する`,
