        body: `▼ゼロから：柱は「押しつぶされる力」と「曲げる力」を同時に受ける
・RC造の柱は、上階からの鉛直荷重（軸力N）と、地震時の水平力による曲げモーメントMを同時に受ける★
・曲げだけ、軸力だけを個別に検討するのではなく、両者の組合せで耐力を評価する必要がある（M-N相関）
⚠ 軸力が大きすぎても小さすぎても、曲げに対する耐力は低下する傾向がある点が直感に反しやすい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 M-N相関図の基本的な形
━━━━━━━━━━━━━━━━━━━━━━
・横軸に曲げモーメントM、縦軸に軸力Nをとった相関図（M-N interaction diagram）で、安全な組合せの範囲を表す★
・軸力Nがゼロに近い（引張側に近い）場合は、鉄筋の引張降伏が支配的になり曲げ耐力は低下する
・軸力Nが釣合い軸力（コンクリートの圧縮破壊と鉄筋の引張降伏が同時に起きる軸力）付近で曲げ耐力は最大になる★
・軸力Nが非常に大きい（圧縮が支配的）場合、コンクリートの圧縮破壊が先行し、曲げ耐力はむしろ低下する

━━━━━━━━━━━━━━━━━━━━━━
🔑 設計上の注意点
━━━━━━━━━━━━━━━━━━━━━━
・地震時、柱には転倒モーメントの影響で軸力が増減する（片側の柱は軸力増加、反対側は軸力減少）★
・軸力が減少する側の柱（引張側に近づく柱）は曲げ耐力が低下しやすく、特に注意が必要な場合がある
・高軸力比（軸力が柱の圧縮耐力に対して大きい割合を占める状態）の柱は、靭性（粘り強さ）が低下しやすい★

【図解】軸力と曲げ耐力の関係（概念）
　軸力の状態｜曲げ耐力への影響
　軸力ゼロ〜小｜鉄筋の引張降伏が支配的、耐力は比較的低い
　釣合い軸力付近｜曲げ耐力が最大となる★
　高軸力（圧縮大）｜コンクリート圧縮破壊が先行、耐力低下・靭性低下★

★ここだけ暗記
・柱の曲げ耐力は軸力の大きさで変化する（M-N相関）
・高軸力比の柱は靭性が低下しやすく注意が必要`,
