        emoji: '🏗️',
        body: `▼ゼロから：基礎は「建物の重さを地盤に伝える最後の砦」
・RC造の直接基礎には、柱ごとに独立して設ける独立フーチング基礎、柱列に沿って連続させる布基礎（連続フーチング）、建物全体の底面を一体のスラブとするべた基礎がある★
・一級では各形式の特徴と、地盤の支持力・不同沈下対策としての選定の考え方が問われる
⚠ 基礎の選定は上部構造の重さだけでなく、地盤の支持力・均一性にも左右される★

━━━━━━━━━━━━━━━━━━━━━━
🔑 独立フーチング基礎と布基礎
━━━━━━━━━━━━━━━━━━━━━━
・独立フーチング基礎：柱ごとに独立した基礎を設ける形式。比較的良好な地盤で、柱の荷重が明確な場合に適する★
・布基礎（連続フーチング）：壁や柱列に沿って連続させた基礎で、荷重を線状に分散できる
・フーチングの底面積は、柱の軸力を地盤の許容支持力で割って必要面積を算定する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 べた基礎の特徴
━━━━━━━━━━━━━━━━━━━━━━
・べた基礎は建物全体の底面を一体のRCスラブで覆う形式で、接地面積が大きく地盤反力を分散できる★
・軟弱地盤や不同沈下のリスクがある敷地で、荷重を広く分散させたい場合に有利
・基礎全体が一体となっているため、部分的な不同沈下に対しても建物全体で抵抗しやすい★
・一方で、材料（コンクリート・鉄筋）の使用量は独立フーチングより多くなる傾向がある

【図解】基礎形式の選定の考え方
　基礎形式｜適した地盤・状況
　独立フーチング｜地盤が良好で柱の荷重が明確な場合★
　布基礎｜壁・柱列に沿って荷重を分散したい場合
　べた基礎｜軟弱地盤、不同沈下対策を重視する場合★

★ここだけ暗記
・フーチング底面積＝柱軸力／地盤の許容支持力
・べた基礎は接地面積が大きく不同沈下対策に有利`,
