        emoji: '🔩',
        body: `▼ゼロから：ボルトは「締め付けた摩擦力」で力を伝える
・鉄骨造の高力ボルト接合は、ボルトを強く締め付けることで生じる部材間の摩擦力によって力を伝達する「摩擦接合」が基本★
・一級では、必要なボルト本数の考え方、すべり係数が耐力に与える影響が頻出
⚠ 高力ボルトは「ボルト自体がせん断力でちぎれる」のではなく「部材同士が滑り出す」ことで耐力が決まる点が普通のボルトと違う★

━━━━━━━━━━━━━━━━━━━━━━
🔑 すべり係数の役割
━━━━━━━━━━━━━━━━━━━━━━
・すべり係数は、接合面同士の摩擦のしやすさ（滑りにくさ）を表す係数で、接合面の処理状態によって変わる★
・接合面に黒皮（ミルスケール）や塗装が残っていると摩擦が不安定になりやすく、すべり係数が低下する
・ブラスト処理や自然発錆処理により接合面を粗面化すると、すべり係数が高まり接合がより確実になる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 必要ボルト本数の考え方
━━━━━━━━━━━━━━━━━━━━━━
・1本の高力ボルトが負担できる許容せん断力は、ボルトの軸力（締付け力）×すべり係数×摩擦面数で決まる★
・摩擦面数は、添え板を両側に配置する「両面せん断」の方が、片側だけの「片面せん断」より多くの力を伝達できる
・必要本数＝設計せん断力／1本あたりの許容せん断力、で算定し、切り上げて配置する★

【図解】高力ボルト接合の性能を左右する要素
　要素｜影響
　すべり係数｜接合面処理が粗いほど高くなる★
　摩擦面数｜両面せん断は片面せん断の2倍近い耐力
　ボルト軸力（締付け力）｜大きいほど摩擦力（耐力）が増す★

★ここだけ暗記
・高力ボルトは摩擦接合、すべり係数は接合面処理で変わる
・両面せん断は片面せん断よりボルト本数を減らせる`,
