        body: `▼ゼロから：壁倍率は「その壁がどれだけ強いか」を表す数字
・壁倍率とは、木造の耐力壁の強さを、一定の基準となる筋かい（厚さ1.5cm×幅9cmの筋かい）を1.0として相対的に表した指標★
・一級では、筋かいの太さ・たすき掛けの有無、面材耐力壁の種類ごとの壁倍率の考え方が問われる
⚠ 壁倍率は単純に厚い・太いほど高くなるわけではなく、材料・工法ごとに試験で定められた値を用いる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 筋かいによる耐力壁
━━━━━━━━━━━━━━━━━━━━━━
・筋かいは柱と横架材の間に斜めに入れる部材で、太さ（厚さ）が増すほど壁倍率は高くなる傾向がある★
・片筋かい（1方向のみ）とたすき掛け筋かい（X字に2方向）では、たすき掛けの方が壁倍率は高くなる★
・筋かいは引張・圧縮どちらの力にも対応できるが、圧縮側では座屈に注意が必要な場合がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 面材耐力壁
━━━━━━━━━━━━━━━━━━━━━━
・構造用合板や石膏ボードなどの面材を柱・間柱に釘打ちして一体化させる耐力壁★
・面材の種類・厚さ・釘のピッチ（打つ間隔）によって壁倍率が変わり、釘ピッチが密なほど壁倍率は高くなる傾向
・筋かいと面材を併用する場合、それぞれの壁倍率を単純に合算できる場合とできない場合があり、上限（合算の限度）が定められている★

【図解】壁倍率の考え方の目安
　耐力壁の種類｜壁倍率への影響要因
　筋かい｜太さ、片筋かい／たすき掛けの別★
　面材耐力壁｜面材の種類・厚さ、釘のピッチ★
　併用壁｜合算に上限あり、単純倍にならない場合がある

★ここだけ暗記
・壁倍率は基準の筋かいを1.0とした相対的な強さの指標
・筋かいのたすき掛けや面材の釘ピッチが密なほど壁倍率は高い`,
