        emoji: '🪨',
        body: `▼ゼロから：地盤が「どれだけの重さに耐えられるか」を計算する
・地盤の極限支持力（地盤が破壊に至る限界の荷重）を推定する代表的な理論式にテルツァギの支持力式がある★
・一級では、支持力に影響する要因（基礎の幅、根入れ深さ、地盤の強度定数）の関係が問われる
⚠ 支持力は基礎の形状（帯状・正方形・円形）によっても補正係数が異なる点に注意★

━━━━━━━━━━━━━━━━━━━━━━
🔑 支持力に影響する主な要因
━━━━━━━━━━━━━━━━━━━━━━
・地盤の粘着力c、内部摩擦角φ（土の強度定数）が大きいほど支持力は増加する★
・基礎の根入れ深さDfが深いほど、周囲の土被り圧による拘束効果で支持力は増加する傾向がある★
・基礎の幅Bが広いほど、支持力は（形状による補正はあるが）一般に増加する

━━━━━━━━━━━━━━━━━━━━━━
🔑 極限支持力と許容支持力
━━━━━━━━━━━━━━━━━━━━━━
・テルツァギの式で求まるのは地盤が破壊に至る極限支持力であり、設計に使う許容支持力はこれを安全率で除して求める★
・安全率は一般に3程度を見込むことが多く、沈下量の検討も別途必要になる場合がある
・支持力が不足する場合は、基礎幅を広げる、根入れを深くする、または地盤改良を行うなどの対策をとる★

【図解】支持力を高める設計上の工夫
　工夫｜効果
　根入れを深くする｜周囲の拘束効果で支持力増加★
　基礎幅を広げる｜接地圧を下げ支持力に対する余裕を増やす
　地盤改良｜地盤そのものの強度定数（c、φ）を向上★

★ここだけ暗記
・支持力は地盤の強度定数（c、φ）、根入れ深さ、基礎幅に左右される
・許容支持力＝極限支持力／安全率（一般に3程度）`,
