        emoji: '🔗',
        body: `▼ゼロから：固定法は「一度固定してから少しずつ解放する」イメージ
・固定法（モーメント分配法）の計算手順を、連続梁（2スパンの連続する梁）を例に確認する★
・一級の学科では計算そのものより、分配率・到達率の考え方の理解が問われることが多い
⚠ 分配率は各部材の剛比の比率で決まり、到達率は代表的に1／2とされることが多い★

━━━━━━━━━━━━━━━━━━━━━━
🔑 分配率の求め方
━━━━━━━━━━━━━━━━━━━━━━
・ある節点に集まる部材の分配率は、各部材の剛比をその節点に集まる剛比の合計で割って求める★
・例えば剛比2と剛比3の部材が1節点に集まる場合、分配率はそれぞれ2／5、3／5となる
・剛比が大きい部材ほど、不つり合いモーメントの大きな割合を引き受ける（分配される）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 分配と到達の繰り返し
━━━━━━━━━━━━━━━━━━━━━━
・まず全節点を固定したと仮定し、各部材の固定端モーメントを求める
・1つの節点を解放し、不つり合いモーメントを分配率に応じて分配する★
・分配されたモーメントの半分（到達率1／2が代表的）が、隣接する節点の反対側の端部に「到達」する
・この分配と到達を、各節点で順番に、十分小さくなるまで繰り返すことで最終的なモーメントに収束させる★

【図解】固定法の計算ステップ
　ステップ｜内容
　①固定端モーメントの算定｜全節点を固定と仮定して算出
　②分配｜不つり合いモーメントを剛比の分配率で分配★
　③到達｜分配の一部（代表的に1／2）が隣接節点へ伝わる★
　④収束まで②③を繰り返す

★ここだけ暗記
・分配率＝その部材の剛比／節点に集まる剛比の合計
・到達率は代表的に1／2とされる`,
