        body: `▼ゼロから：ピロティは「見た目はかっこいいが地震には弱い」典型例
・ピロティとは、建物の1階部分を柱だけの開放的な空間とし、壁を設けない建築形式★
・一級では、ピロティ階がなぜ地震に弱くなりやすいか、その対策が問われる
⚠ ピロティ階は上階に比べて壁（耐震要素）が極端に少なく、剛性が急激に低下した「弱層」になりやすい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 ピロティ階が弱層になる理由
━━━━━━━━━━━━━━━━━━━━━━
・上階には間仕切り壁や外壁など、耐震要素として働く壁が多く存在する
・ピロティ階は開放性を確保するため、これらの壁がほとんどなく、柱だけで水平力に抵抗する★
・剛性率（各階の剛性のバランス）を計算すると、ピロティ階だけ突出して小さくなりやすい
・地震時には、剛性の低い階に変形が集中しやすいため、ピロティ階の柱に過大な変形・損傷が集中する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 ピロティ構造への対策
━━━━━━━━━━━━━━━━━━━━━━
・ピロティ階の柱の断面を大きくし、靭性（粘り強さ）を特に高める設計とする★
・やむを得ずピロティとする場合、構造特性係数Dsの割増しなど、保有水平耐力計算上の配慮が求められる
・可能であれば、ピロティ階にも最小限の耐震壁やブレースを計画的に配置し、剛性の急変を緩和する★

【図解】ピロティ階の問題点と対策
　項目｜内容
　問題点｜耐震要素（壁）が少なく剛性率が突出して低下★
　リスク｜地震時にピロティ階へ変形が集中★
　対策｜柱の靭性強化、Dsの割増し、最小限の耐震要素配置★

★ここだけ暗記
・ピロティ階は耐震要素が少なく剛性率が低下しやすい弱層
・柱の靭性強化とDsの割増しなどで対策する`,
