        emoji: '🩺',
        body: `▼ゼロから：既存建物の「今の耐震性能」を数値で評価する
・耐震診断は、既存建築物（特に旧耐震基準で建てられたもの）の耐震性能を評価する手続き★
・一級では、診断結果の指標であるIs値（構造耐震指標）の意味と判定基準が問われる
⚠ 耐震診断は新築の構造計算とは別の考え方・計算式を用いる点に注意（既存建物向けの簡易な評価体系）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 Is値（構造耐震指標）の構成
━━━━━━━━━━━━━━━━━━━━━━
・Is値は、強度（E0：保有性能基本指標）、形状（SD：形状指標）、経年（T：経年指標）の要素を掛け合わせて求める★
・強度（耐力）が高いほどIs値は大きくなるが、平面・立面の形状が悪い（SDが小さい）、経年劣化が大きい（Tが小さい）とIs値は低下する
・一般にIs値0.6以上であれば、大地震に対して倒壊・崩壊する危険性が低いと判定される目安とされる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 耐震診断と新築の構造計算の違い
━━━━━━━━━━━━━━━━━━━━━━
・耐震診断は既存の実際の建物を対象に、簡易な方法（1次診断〜3次診断の段階がある）で耐震性能を評価する★
・診断のレベルが上がる（1次→2次→3次）ほど、より詳細な検討を行い、精度の高い評価が得られる
・診断結果に応じて、耐震改修（補強）の要否・方法を検討する流れになる

【図解】Is値の構成と目安
　要素｜内容
　E0（保有性能基本指標）｜強度と靭性から求まる基本的な耐力指標★
　SD（形状指標）｜平面・立面の形状の良し悪しを反映
　T（経年指標）｜建物の経年劣化を反映
　Is値の目安｜0.6以上で倒壊・崩壊の危険性が低いとされる★

★ここだけ暗記
・Is値＝E0×SD×T（強度・形状・経年の積）
・Is値0.6以上が倒壊・崩壊の危険性が低いとされる目安`,
