　立面が単純（直方体）｜剛性率のバランスが取りやすい★
　凹凸が多い平面・急なセットバック｜偏心率・剛性率が悪化しやすい★

★ここだけ暗記
・整形な平面・立面ほど偏心率・剛性率のバランスが取りやすい
