【図解】現場打ちRC造とプレキャスト構造の比較
　項目｜現場打ちRC造｜プレキャスト構造
　施工の一体性｜一体打設で連続性が高い｜接合部の設計・施工が重要★
　工期｜型枠・養生に時間を要する｜現場工程が短縮されやすい★
　品質の安定性｜現場条件に左右されやすい｜工場製作で安定しやすい

★ここだけ暗記
・プレキャスト構造は工期短縮・品質安定が利点
