　得られる情報｜荷重変形曲線、崩壊形、保有水平耐力★
　活用場面｜耐震性能の精査、耐震改修効果の確認

★ここだけ暗記
・プッシュオーバー解析は水平荷重を段階的に増加させる静的解析
