        emoji: '🛞',
        body: `▼ゼロから：ゴムの「非線形な」性質を単純な数値に置き換える工夫
・免震構造の積層ゴムは、変形が大きくなるほど剛性が変化する非線形な性質をもつことが多く、簡易な評価には等価剛性・等価減衰という考え方が使われる★
・一級では、等価剛性・等価減衰の意味と、免震構造の応答評価での使われ方が問われる
⚠ 等価剛性は、ある変形レベルにおける免震装置の「見かけ上の線形剛性」として近似的に扱うための値である★

━━━━━━━━━━━━━━━━━━━━━━
🔑 等価剛性の考え方
━━━━━━━━━━━━━━━━━━━━━━
・免震装置（積層ゴム等）の荷重-変形関係は、履歴ループ（荷重をかけて戻す過程で描く曲線）を描く非線形な挙動を示す★
・等価剛性は、このループのピーク時の荷重をピーク時の変形で割った値として定義され、線形ばねとして近似的に扱う
・免震構造の固有周期の評価などに、この等価剛性を用いることが多い★

━━━━━━━━━━━━━━━━━━━━━━
🔑 等価減衰の考え方
━━━━━━━━━━━━━━━━━━━━━━
・履歴ループが囲む面積は、1サイクルの変形で吸収されたエネルギー量を表し、これをもとに等価減衰定数を算定する★
・履歴ループの面積が大きい（エネルギー吸収が大きい）免震装置ほど、等価減衰定数は大きくなる
・等価減衰定数が大きいほど、地震応答（建物の揺れ）を効果的に低減できると評価される★

【図解】等価剛性・等価減衰の意味
　指標｜求め方（概念）｜用途
　等価剛性｜ピーク荷重／ピーク変形★｜固有周期の評価
　等価減衰定数｜履歴ループの面積（吸収エネルギー）から算定★｜応答低減効果の評価

★ここだけ暗記
・等価剛性は非線形な免震装置を線形ばねとして近似する考え方
・等価減衰定数は履歴ループの面積（吸収エネルギー）から求まる`,
