        body: `▼ゼロから：「仮想の1の力」を使ってたわみを求める技
・単位荷重法（仮想仕事法の一種）は、求めたい位置・方向に単位（1の）仮想荷重を与え、実際の荷重による変形との仕事の関係からたわみを求める手法★
・一級では、複雑な形状の梁やラーメンのたわみを求める際の考え方の基礎として問われる
⚠ 単位荷重法は、公式が用意されていない複雑な荷重・形状の変形にも対応できる汎用的な方法★

━━━━━━━━━━━━━━━━━━━━━━
🔑 単位荷重法の基本的な考え方
━━━━━━━━━━━━━━━━━━━━━━
・求めたい点・方向に仮想の単位荷重（大きさ1）を作用させ、そのときの部材内の曲げモーメント分布m(x)を求める★
・実際の荷重による曲げモーメント分布M(x)も別途求めておく
・たわみ（または回転角）＝∫M(x)・m(x)／EI dx という積分（または図形的な面積計算）で求められる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 図形的な計算（モーメント面積法との関係）
━━━━━━━━━━━━━━━━━━━━━━
・実務・学科では、積分の代わりにM図とm図の面積・重心を使った図形的な計算（モーメント面積による方法）がよく使われる★
・単純な形状（三角形・台形のM図）であれば、面積と図心の位置から比較的簡単にたわみを求められる
・この手法は、不静定構造の解析（力法）の基礎としても重要な考え方になる★

【図解】単位荷重法の手順
　手順｜内容
　①｜求めたい点に仮想の単位荷重を与えm図を求める
　②｜実際の荷重によるM図を求める★
　③｜M図とm図の積（面積）の積分でたわみを求める★

★ここだけ暗記
・単位荷重法はM(x)とm(x)の積の積分でたわみを求める汎用的手法
・実務ではM図・m図の面積計算で代用することが多い`,
