        body: `▼ゼロから：隣り合う3つの支点のモーメントを結びつける式
・3モーメントの定理は、連続梁の隣接する3つの支点における曲げモーメントの関係を1本の式で表す、不静定梁の代表的な解法の1つ★
・一級では、3モーメントの定理がどのような場面で使われるかという概要の理解が問われる
⚠ 3モーメントの定理は等スパン・等断面の連続梁で特に扱いやすく、支点数が多いほど連立方程式も増える★

━━━━━━━━━━━━━━━━━━━━━━
🔑 3モーメントの定理の考え方
━━━━━━━━━━━━━━━━━━━━━━
・隣接する2つのスパンについて、両端と中間支点、合計3つの支点の曲げモーメントの関係式を立てる★
・この関係式に、各スパンの荷重条件（単純梁として見た場合のモーメント面積）を代入して連立方程式を解く
・支点の数だけ連立方程式が必要になり、支点が多いほど手計算は煩雑になる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 実務・学科での位置づけ
━━━━━━━━━━━━━━━━━━━━━━
・現在の実務では、コンピュータによる解析（マトリクス法等）が一般的で、3モーメントの定理を手計算で解くことは少ない★
・学科試験では、連続梁が不静定構造であり、単純梁の組合せだけでは解けないことの理解、代表的な解法の名称を押さえておけば十分な場合が多い
・対称な荷重・支持条件であれば、対称性を利用して計算を簡略化できる場合もある★

★ここだけ暗記
・3モーメントの定理は隣接する3支点のモーメントの関係式
・連続梁の代表的な不静定解析手法の1つとして名称を押さえる`,
