        body: `▼ゼロから：まっすぐ押しても「わずかなズレ」で曲げが生じる
・圧縮力の作用位置が部材の図心からわずかにずれている（偏心している）場合や、部材に初期たわみがある場合、圧縮力そのものが追加の曲げモーメントを生じさせることがある★
・一級では、この現象（P-Δ効果とも呼ばれる）の考え方が問われる
⚠ 偏心が小さくても、荷重Pが大きいと、生じる付加曲げモーメント（P×偏心量）は無視できない大きさになることがある★

━━━━━━━━━━━━━━━━━━━━━━
🔑 P-Δ効果の考え方
━━━━━━━━━━━━━━━━━━━━━━
・柱が水平方向にΔだけ変位した状態で、鉛直荷重Pが作用し続けると、P×Δという追加の転倒モーメントが生じる★
・この追加モーメントによってさらに変位が増え、変位が変位を呼ぶ（二次的な）効果が生まれる
・P-Δ効果は、建物の変形が大きい（層間変形角が大きい）ほど顕著になり、特に高層建築物や塔状比の大きい建物で考慮が必要★

━━━━━━━━━━━━━━━━━━━━━━
🔑 設計上の配慮
━━━━━━━━━━━━━━━━━━━━━━
・層間変形角を一定以下に抑える設計とすることで、P-Δ効果による付加的な影響を抑制できる★
・保有水平耐力計算などの高度な検討では、P-Δ効果を考慮した解析を行うことが求められる場合がある
・偏心圧縮材そのものの設計では、軸力による圧縮応力度に加え、偏心による曲げ応力度を加算して検討する★

★ここだけ暗記
・P-Δ効果は変位Δに荷重Pが作用し続けることで生じる付加的な転倒モーメント
・層間変形角を抑えることでP-Δ効果の影響を抑制できる`,
