        body: `▼ゼロから：風は「押す」だけでなく「揺らす」こともある
・風による建物の振動現象には、静的な風圧力だけでなく、渦励振やギャロッピングのような動的な振動現象もある★
・一級では、これらの風による振動現象の概要と、対策の考え方が問われる
⚠ これらの現象は、特に細長い塔状の建物や、軽量で柔軟な構造物で問題になりやすい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 渦励振（カルマン渦による振動）
━━━━━━━━━━━━━━━━━━━━━━
・風が円柱状・角柱状の構造物を通過する際、背後に周期的な渦（カルマン渦）が発生し、構造物に周期的な力を及ぼす現象★
・この渦の発生周期が構造物の固有周期に近づくと、共振して大きな振動（渦励振）が生じることがある★
・塔状の構造物（煙突、タワー等）で特に注意が必要な現象

━━━━━━━━━━━━━━━━━━━━━━
🔑 ギャロッピングとフラッター
━━━━━━━━━━━━━━━━━━━━━━
・ギャロッピングは、断面形状によって生じる空気力学的な不安定現象で、振動が風速の増加とともに自己増幅していく現象★
・フラッターは、構造物のねじれ振動と曲げ振動が連成することで生じる、より複雑な空気力学的不安定現象
・これらの対策として、断面形状の工夫（角を丸める等）や、制振装置（TMD等）の設置が検討される★

【図解】風による動的振動現象
　現象｜主な原因｜対策の方向性
　渦励振｜カルマン渦と固有周期の共振★｜断面形状の工夫、制振装置
　ギャロッピング｜断面形状による空気力学的不安定｜断面形状の改善★

★ここだけ暗記
・渦励振はカルマン渦の発生周期と構造物の固有周期の共振で生じる
・塔状構造物では断面形状の工夫や制振装置で対策する`,
