        title: '山留め壁の土圧算定',
        emoji: '🧱',
        body: `▼ゼロから：壁は「土が崩れようとする力」を受け止めている
・山留め壁の設計では、壁に作用する土圧（主働土圧・受働土圧）を正しく評価することが重要な出発点となる★
・一級では、主働土圧・受働土圧の考え方と、山留め壁への作用の仕方が問われる
⚠ 土圧は単純な静止状態の圧力ではなく、壁の変位の方向によって主働側・受働側で大きさが大きく異なる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 主働土圧と受働土圧
━━━━━━━━━━━━━━━━━━━━━━
・主働土圧：壁が地盤から離れる方向にわずかに変位した結果、地盤が緩んで生じる、比較的小さい土圧★
・受働土圧：壁が地盤を押し込む方向に変位した結果、地盤が圧縮されて生じる、主働土圧よりはるかに大きい土圧★
・掘削側（根切り側）の地盤は受働土圧として壁を支え、背面側（土がある側）は主働土圧として壁を押す

━━━━━━━━━━━━━━━━━━━━━━
🔑 土圧の大きさに影響する要因
━━━━━━━━━━━━━━━━━━━━━━
・土の内部摩擦角（土の種類・締まり具合）が大きいほど、主働土圧は小さく、受働土圧は大きくなる傾向がある★
・地下水位が高い場合、土圧に加えて水圧も壁に作用するため、設計上の荷重が増大する
・山留め壁の変位量が土圧の大きさに影響するため、変位を抑える設計（切ばり等の支保工）が重要になる★

【図解】主働土圧と受働土圧の違い
　土圧の種類｜生じる条件｜大きさの傾向
　主働土圧｜壁が地盤から離れる方向に変位｜比較的小さい★
　受働土圧｜壁が地盤を押し込む方向に変位｜主働土圧よりはるかに大きい★

★ここだけ暗記
・主働土圧は壁が地盤から離れる側、受働土圧は壁が地盤を押す側に生じる
・受働土圧は主働土圧よりはるかに大きい`,
