        emoji: '🧱',
        body: `▼ゼロから：擁壁は「土を留める壁」として独自の安定検討が必要
・擁壁は、高低差のある地盤を保持するための構造物で、土圧に対して転倒・滑動・支持力（地盤破壊）の3つの安定性を検討する必要がある★
・一級では、擁壁に特有の安定検討項目が問われる
⚠ 擁壁は建物本体とは別に、単独で土圧に対する安定性を確保する必要がある★

━━━━━━━━━━━━━━━━━━━━━━
🔑 擁壁の3つの安定検討
━━━━━━━━━━━━━━━━━━━━━━
・転倒に対する安定：擁壁が土圧によって前方に転倒しないか、擁壁底面を基準にモーメントのつり合いで確認する★
・滑動に対する安定：擁壁底面と地盤との摩擦抵抗が、土圧による水平力に対して十分かを確認する★
・支持力（沈下）に対する安定：擁壁底面の接地圧が、地盤の許容支持力を超えないかを確認する

━━━━━━━━━━━━━━━━━━━━━━
🔑 擁壁の形式
━━━━━━━━━━━━━━━━━━━━━━
・重力式擁壁：擁壁自体の重量で土圧に抵抗する形式で、比較的低い擁壁に用いられる★
・片持ち梁式（L型・逆T型）擁壁：底版と壁体を一体化し、底版上の土の重量も利用して安定を確保する形式★
・控え壁式擁壁：壁体に控え壁を付けて剛性を高め、より高い擁壁にも対応できる形式

【図解】擁壁の安定検討の全体像
　検討項目｜確認すること
　転倒｜擁壁底面まわりのモーメントのつり合い★
　滑動｜底面の摩擦抵抗と水平力の比較★
　支持力｜底面の接地圧と地盤の許容支持力の比較

★ここだけ暗記
・擁壁は転倒・滑動・支持力の3つの安定性を検討する
・形式は重力式・片持ち梁式（L型等）・控え壁式などがある`,
