        title: 'RC梁のひび割れ制御',
        emoji: '🧱',
        body: `▼ゼロから：ひび割れは「ゼロにする」のではなく「制御する」もの
・RC構造は、引張側のコンクリートにひび割れが生じることを前提に設計されており、ひび割れ自体を完全になくすことは現実的ではない★
・一級では、ひび割れを許容範囲内に制御するための設計上の考え方が問われる
⚠ 過大なひび割れ幅は、美観だけでなく、鉄筋の腐食（水や空気の侵入経路になる）につながるため制御が必要★

━━━━━━━━━━━━━━━━━━━━━━
🔑 ひび割れ幅に影響する要因
━━━━━━━━━━━━━━━━━━━━━━
・鉄筋の応力度が大きいほど、ひび割れ幅は大きくなる傾向がある★
・鉄筋を細く多数配置する（同じ鉄筋量でも本数を増やす）方が、太い鉄筋を少数配置するより、ひび割れが分散し1本あたりのひび割れ幅は小さくなる★
・かぶり厚さが大きいほど、コンクリート表面でのひび割れ幅は大きく見えやすい傾向がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 ひび割れ制御の設計上の工夫
━━━━━━━━━━━━━━━━━━━━━━
・使用性（ひび割れ幅の制限）を踏まえた鉄筋量・配置の検討（ひび割れ幅の計算による照査）を行う★
・温度変化・乾燥収縮によるひび割れを抑えるため、適切な間隔で収縮・温度応力用の鉄筋（配力筋等）を配置する
・コンクリートの調合（水セメント比を小さくする等）により、乾燥収縮そのものを抑制することも有効★

★ここだけ暗記
・ひび割れ幅は鉄筋応力度が大きいほど、鉄筋を太く少数配置するほど大きくなりやすい
・水セメント比を小さくするなど乾燥収縮の抑制も重要な対策`,
