━━━━━━━━━━━━━━━━━━━━━━
・耐力壁線間距離の確認は、個々の耐力壁の壁量確認とは別に行う、平面バランスに関する検討の1つ★
・大きな吹抜けや広い無耐力壁区画がある場合、耐力壁線間距離が過大になりやすく注意が必要
