・BRB等の履歴型ダンパーは、主に変形の「大きさ」に応じて抵抗力・吸収エネルギーが決まる（変位依存型）★
・オイルダンパー等の粘性（速度依存）型ダンパーは、変形の「速さ」に応じて抵抗力が変化する
・建物の揺れの特性（地震か風か、変形速度の大小）に応じて、適したダンパーの種類を選定することが重要★

★ここだけ暗記
