        body: `▼ゼロから：鋼材にも「用途に応じた規格」がある
・建築構造用の鋼材にはいくつかの規格（JIS規格）があり、それぞれ求められる性能（強度・溶接性・じん性等）が異なる★
・一級では、代表的な鋼材規格の違いが問われる
⚠ 建築構造物には、一般の鋼材規格より建築特有の要求性能（溶接性、降伏比等）を考慮したSN材が広く使われている★

━━━━━━━━━━━━━━━━━━━━━━
🔑 SN材（建築構造用圧延鋼材）
━━━━━━━━━━━━━━━━━━━━━━
・SN材は建築構造物のために開発された鋼材規格で、A種・B種・C種に区分され、要求性能が異なる★
・B種・C種は、降伏比の上限（降伏点が引張強さに対して高すぎないこと）や、溶接性（炭素当量の上限）が規定されており、耐震設計に適している★
・C種はさらに板厚方向の性能（ラメラテア等の防止）も要求され、ダイアフラム等、板厚方向に大きな力を受ける部位に用いられる

━━━━━━━━━━━━━━━━━━━━━━
🔑 SS材・SM材との違い
━━━━━━━━━━━━━━━━━━━━━━
・SS材（一般構造用圧延鋼材）は、機械的性質の規定はあるが、SN材ほど溶接性・じん性に関する厳密な規定はない★
・SM材（溶接構造用圧延鋼材）は、SS材より溶接性に配慮した規格で、橋梁等にもよく使われる
・建築物の主要な構造部材には、耐震性能の観点からSN材が広く採用されている★

★ここだけ暗記
・SN材は建築構造物向けに開発された規格でA〜C種に区分される
・C種は板厚方向性能も要求され、ダイアフラム等に用いられる`,
