        emoji: '🏢',
        body: `▼ゼロから：耐震壁は「量」だけでなく「どこに置くか」が重要
・耐震壁（RC造の壁、鉄骨のブレース等）の配置計画では、量的な充足だけでなく、平面上のバランス（偏りの有無）が極めて重要★
・一級では、配置バランスが悪い場合に生じる問題と、良い配置の考え方が問われる
⚠ 耐震要素が平面の一部（例えば建物の片側）に偏って配置されると、重心と剛心のズレ（偏心）が大きくなる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 偏心が生じるメカニズム
━━━━━━━━━━━━━━━━━━━━━━
・建物の重さの中心（重心）と、耐震要素による抵抗力の中心（剛心）がずれていると、地震時に建物がねじれながら変形する★
・ねじれ変形が生じると、剛心から離れた位置にある耐震要素ほど、より大きな変形を強いられ、損傷が集中しやすくなる
・偏心率はこの重心と剛心のズレの程度を表す指標で、一定値を超えると構造計算上、不利な補正（Fes等）が必要になる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 良い配置計画の考え方
━━━━━━━━━━━━━━━━━━━━━━
・耐震壁・ブレースは、できるだけ平面の外周部・対称な位置にバランスよく配置することが望ましい★
・意匠計画上の制約（開口部の位置等）で配置に偏りが生じる場合、他の位置に耐震要素を追加するなどして補正を図る
・平面形状が複雑な場合、エキスパンションジョイントで単純な形状に分割することも、バランス確保の一手段となる★

★ここだけ暗記
・耐震壁の配置が偏ると重心と剛心がずれ地震時にねじれが生じやすい
・できるだけ外周部・対称な位置にバランスよく配置することが望ましい`,
