・風は地震と異なり、継続的に（繰り返し、あるいは一方向に持続的に）作用する荷重であるため、免震層の変形・居住性への影響の仕方が異なる
・強風時に免震建物が過度に揺れると、居住者の不快感や、設備配管への繰り返し負担につながるおそれがある★

