・免震装置に適度な減衰性能（鉛プラグ入り積層ゴムや、ダンパーの付加等）を持たせ、風揺れを抑制する★
・風に対する初期剛性を確保しつつ、大地震時には十分な変形性能を発揮できるよう、装置の特性をバランスよく設計する
・建物の形状・高さによる風荷重の影響を踏まえ、必要に応じて風洞実験等で風揺れ性状を確認することもある★

